-- 099_exam_tactics_examples.sql
--
-- Kullanici geri bildirimi (23 Kasim 2026): "ornekler cok olmali" --
-- exam_tactics.worked_example_tr her satirda TEK bir uygulanmis ornek
-- tasiyordu. Bu migration examples_tr (text[]) kolonunu ekler ve mevcut
-- 25 satirin HER BIRINE, worked_example_tr degerini korurken, AYNI
-- taktigi FARKLI bir cumle/senaryoda gosteren IKINCI bir ornek daha
-- ekler -- boylece her taktik artik en az 2 ornekle gosteriliyor (bkz.
-- backend/app/schemas/exams.py::ExamTacticItem.examples_tr, mobile/web
-- exam-tactics ekranlari).
--
-- worked_example_tr kolonu KASITLI OLARAK SILINMEDI -- backend henuz bu
-- migration+kod degisikligiyle birlikte yeniden deploy edilmeden once
-- canli backend o kolonu hala SELECT ediyor olabilir; kod deploy
-- edildikten sonra ayri, kucuk bir temizlik migration'iyla (DROP COLUMN)
-- kaldirilabilir.

ALTER TABLE public.exam_tactics ADD COLUMN IF NOT EXISTS examples_tr text[];

UPDATE public.exam_tactics AS et
SET examples_tr = ARRAY[et.worked_example_tr, v.second_example]
FROM (VALUES
  ('618e854c-8d19-4533-bc11-e9c7d908320f'::uuid, $ex$"The committee praised the proposal for its innovative approach; __________, several members raised concerns about its feasibility." İlk yargı olumlu (praised), ikinci yargı sorunlu bir durumdan bahsediyor (concerns) — beklenti kırıcı bir bağlaç gerekir. Doğru cevap "nevertheless"tir; "furthermore" (ekleme, aynı yönde devam) veya "as a result" (sonuç) bu zıtlığı karşılamadığı için elenir.$ex$),
  ('c004c79a-c766-436f-9e28-b4857404ef42'::uuid, $ex$"The university expanded its scholarship program; __________, it opened three new research centers this year." İki cümle de olumlu ve birbirine eklenen gelişmelerden bahsediyor, aralarında sebep-sonuç değil pekiştirme ilişkisi var → doğru cevap "moreover" ya da "in addition"dır; "therefore" (sonuç bağlacı) burada aralarında nedensellik olmadığı için yanlıştır.$ex$),
  ('7c22d868-2e33-4369-b962-0417ead3b258'::uuid, $ex$"The engineer ___ designed this bridge studied at a prestigious university." Boşluktan hemen sonra yüklem ("designed") geldiği için zamir ÖZNE konumundadır → "who" ya da "that" kullanılabilir ama ATILAMAZ; "The engineer designed this bridge studied..." şeklinde zamiri tamamen çıkarmak cümleyi anlaşılmaz hale getirir çünkü özne boşlukta kalır.$ex$),
  ('2ecfae88-18b4-48b2-a71d-debf689ef2bf'::uuid, $ex$"Have you finished the report?" she asked him. → She asked him if he had finished the report. Hem soru sırası özne-yükleme döner (do/did yardımcı fiili düşer) hem de "have finished" (present perfect) bir basamak geriye kayarak "had finished" (past perfect) olur, çünkü reporting fiil (asked) geçmiş zamandadır.$ex$),
  ('a3d3a6db-14a1-4e17-a046-0dc42781ce1e'::uuid, $ex$"The lights in her office are off and her car isn't in the parking lot. She ___ have gone home early." Kanıtlar güçlü bir çıkarıma işaret ediyor (ışıklar kapalı, araba yok) → doğru cevap "must have"dir. Ama "I'm not sure, but she ___ be at a meeting right now" cümlesinde kesin bir kanıt olmadığı için zayıf bir olasılık anlatılır ve doğru cevap "might" ya da "could"dur, "must" değil.$ex$),
  ('d9e204e0-755b-48a2-9417-55b55e5fa77f'::uuid, $ex$"This novel ___ into more than twenty languages since its publication." Eylemi kimin yaptığı (çevirmenler) önemsiz, önemli olan romanın başına gelen şey → doğru cevap "has been translated"dır, aktif çatıdaki "has translated" yanlıştır çünkü roman çeviri eylemini kendisi yapamaz.$ex$),
  ('8e4cad68-ff49-4324-a2ca-676cc5d8f832'::uuid, $ex$"If the weather ___ (improve) tomorrow, we will go hiking in the mountains." Gelecekte gerçekleşmesi mümkün bir durum anlatıldığı için Tip 1 kullanılır, if cümleciğinde present simple gerekir → doğru cevap "improves"tir, "will improve" kullanmak if cümleciğinde asla doğru olmaz.$ex$),
  ('9e2c5ca8-24fe-440f-8a63-e336634786ec'::uuid, $ex$"I ___ (visit) Japan three times so far." "So far" (şimdiye kadar) present perfect'in klasik işaretçisi olduğu için doğru cevap "have visited"tir. Ama "I ___ (visit) Japan in 2015." cümlesinde kesin bir geçmiş zaman belirteci ("in 2015") olduğu için present perfect değil past simple ("visited") kullanılması gerekir.$ex$),
  ('319a9471-5479-4d76-adb7-da73d58a2129'::uuid, $ex$"On his way home, he stopped ___ (buy) some bread." Burada durma eyleminin AMACI ekmek almaktır (duruş + amaç) → doğru cevap "to buy"dur. Ama "He stopped ___ (smoke) five years ago." cümlesinde sigara içme eyleminin kendisinin durdurulması anlatıldığı için doğru cevap "smoking"tir — "stop to do" ile "stop doing" tamamen farklı anlamlar taşır.$ex$),
  ('8429f4f4-29d8-46d3-b405-25862bb60e54'::uuid, $ex$"__________ her lack of experience, she was offered the managerial position." Boşluktan sonra bir isim öbeği ("her lack of experience") geldiği için "Even though" yanlıştır — doğru cevap "In spite of" ya da "Despite"tir. Eğer cümle "__________ she lacked experience, she was offered..." şeklinde özne+yüklemli bir cümlecikle devam etseydi, doğru cevap "Even though" olurdu.$ex$),
  ('f0d5f0e7-f466-4ae4-b5e3-28a515599cb0'::uuid, $ex$Bir sonraki cümle "Such measures proved costly for small businesses." ile başlıyorsa, boşluktaki cümlede mutlaka somut, sayılabilir önlemlerden (measures) bahsedilmeli — soyut bir duygu veya tek bir olaydan söz eden bir şık, çoğul referans kelimesi ("such measures") ile uyuşmadığı için elenir.$ex$),
  ('d1f055e1-616e-4792-9199-6a35038852ec'::uuid, $ex$"All the reports ___ submitted by Friday, according to the new policy." Burada sadece modal+edilgen (perfect yok) gerekir → doğru cevap "must be", "must have been" değil, çünkü cümle gelecekteki bir zorunluluğu anlatıyor, geçmişe dönük bir çıkarım değil. "The missing files ___ accidentally deleted last week." cümlesinde ise hem modal hem perfect hem edilgen bir arada gerekir → doğru cevap "might have been"dir.$ex$),
  ('bed5059e-31fb-4397-863e-61db3cb37dc3'::uuid, $ex$"Finish your homework before dinner," the mother told her son. → The mother told her son to finish his homework before dinner. "Tell" mutlaka bir KİŞİ alır ve "kişi + to + fiil" kalıbını kullanır; "told to finish" (kişisiz) ya da "told that finish" gibi bir yapı bu kalıba uymadığı için yanlıştır.$ex$),
  ('fddda164-3aeb-4c84-966a-a662a6df7c6e'::uuid, $ex$"If he ___ (know) the answer, he would raise his hand." Şimdiki zamanda gerçek olmayan bir durum (cevabı bilmiyor) anlatıldığı için doğru cevap "knew"dir, "knows" ya da "will know" değil. "If I ___ (be) in your position, I would accept the offer immediately." cümlesinde ise özne "I" olmasına rağmen doğru cevap yine "were"dir, "was" değil.$ex$),
  ('e8cab074-60e8-43c1-b973-2bb9273e1c43'::uuid, $ex$"I really ___ call my grandmother, I haven't spoken to her in weeks." Bu, dışarıdan gelen bir kural değil, konuşmacının kendi hissettiği kişisel bir sorumluluk olduğu için doğru cevap "must"tur, "have to" değil. "You ___ have told me about the meeting, I missed it completely." cümlesinde geçmişte yapılmayan ve pişmanlık duyulan bir eylem anlatıldığı için doğru cevap "should" (should have told) olur.$ex$),
  ('018a0797-2f2c-4927-9b3a-65aec2dda2de'::uuid, $ex$"He failed the exam, ___ disappointed his parents greatly." Virgülden sonra gelen bu zamir önceki isimlerden birini değil, sınavı geçememe olayının TAMAMINI nitelediği için doğru cevap "which"tir; "that" burada hem virgülden sonra geldiği hem de bir ismi değil tüm cümleyi nitelediği için kesinlikle yanlıştır.$ex$),
  ('31e0ff92-e2bb-492c-9a5c-f6db9135b75a'::uuid, $ex$"The company ___ profits doubled last year plans to expand abroad." Boşluktan sonra bir isim ("profits") var ve bu kâr şirkete ait → doğru cevap "whose"tur. "The hotel ___ was fully booked offered us a room in a different branch." cümlesi ise yanlıştır çünkü "where" özne göreviyle kullanılamaz; doğrusu "The hotel which/that was fully booked..." olmalıdır.$ex$),
  ('b21c688a-8fb8-4768-a0f5-e3c1b588e638'::uuid, $ex$"My grandfather ___ speak four languages fluently." Burada geçmişte genel, sürekli bir yetenek anlatıldığı için doğru cevap "could"dur. Ama "Even though the exam was very difficult, she ___ finish it within the time limit." cümlesinde tek seferlik, belirli bir başarı anlatıldığı için doğru cevap "was able to"dur, "could" değil.$ex$),
  ('e40293c6-8d1c-4fd2-aac0-531a6c8d36c5'::uuid, $ex$"The new regulation, which was introduced last year, has significantly reduced traffic accidents in the city center." → Önce yüklemler belirlenir: "was introduced" (edilgen, geçmiş zaman) ve "has reduced" (present perfect, aktif). Türkçe şıklarda "tanıtılmıştır/getirilmiştir" (edilgen) ile "azaltmıştır" (aktif, güncelliğini koruyan bir sonuç) ikilisini birebir karşılamayan şıklar — düzenlemeyi aktif çatıyla çeviren ya da kaza azalmasını geçmişte kalmış tek seferlik bir olay gibi aktaran şıklar — elenir.$ex$),
  ('aa7cbd8a-9edf-4baf-af4f-7caba80af43f'::uuid, $ex$"If they ___ (invest) in better equipment, the factory wouldn't have suffered such heavy losses." Geçmişte gerçekleşmemiş bir durum (yatırım yapmadılar, zarar ettiler) anlatıldığı için doğru cevap "had invested"tir; "would have invested" if cümleciğinde asla kullanılmaz, bu YDS'nin en sık sorduğu Tip 3 tuzaklarından biridir.$ex$),
  ('b4a94169-96da-4bb3-84d1-3ead6fb9de59'::uuid, $ex$"The flight was delayed __________ a severe storm over the Atlantic." Boşluktan sonra isim öbeği ("a severe storm") geldiği için doğru cevap "because of"tur; "because" yanlıştır çünkü ardından özne+yüklemli tam bir cümlecik gelmemiştir (doğrusu "because there was a severe storm" olurdu).$ex$),
  ('6b3ef7d7-206f-48b3-8886-4129990035b8'::uuid, $ex$"The restaurant, which my colleague recommended, turned out to be excellent." Burada zamir nesne konumunda olsa da (recommended'ın nesnesi) cümlecik virgüllü yani NON-DEFINING olduğu için "which" atılamaz: "The restaurant, my colleague recommended, turned out..." şeklinde zamiri çıkarmak yanlıştır — atma kuralı sadece defining clause'larda geçerlidir.$ex$),
  ('fd48f9bb-1483-4aef-92f6-f6a1cfd26945'::uuid, $ex$"If she ___ (accept) that job offer five years ago, she would be running her own company now." Geçmişteki bir karar (teklifi kabul etmedi) ŞİMDİKİ bir sonucu (şirketi yok) etkilediği için doğru cevap "had accepted"tır (if + past perfect), sonuç kısmında ise "now" kelimesi şimdiki zamana işaret ettiği için "would be running" (would + yalın fiil, "would have run" değil) kullanılmıştır.$ex$),
  ('dac7e7b7-d658-48cf-818f-7a4b6c25a582'::uuid, $ex$"___ I borrow your pen for a second?" Burada resmi bir izin isteme söz konusu → doğru cevap "May" (ya da gündelik dilde "Can"), ama "___ you lower your voice, please? I'm on the phone." cümlesinde izin değil kibar bir rica anlatıldığı için doğru cevap "Could" ya da "Would"dur; "May" burada garip kaçar çünkü "May" karşıdaki kişiden rica etmek için değil izin istemek/vermek için kullanılır.$ex$),
  ('c7009f21-5574-444e-98dd-f1a114d2201d'::uuid, $ex$"The passengers (who were) waiting at the gate were informed about the delay." → "The passengers waiting at the gate were informed about the delay." Burada "waiting" aktif bir eylemi (yolcuların kendi eylemi) anlattığı için -ing (present participle) kullanılır; cümlenin gerçek ana fiili "were informed"dur, "waiting" sadece öznenin durumunu tanımlayan kısaltılmış bir cümleciktir.$ex$)
) AS v(id, second_example)
WHERE et.id = v.id;